import{j as e,b as o}from"./index-D9dhv7y0.js";import{I as t}from"./InfoPage-BFur8oN1.js";import"./PageHeader-rdwdRYQ6.js";function r(){return e.jsx(t,{title:"Visitors",lead:"The Broad Court is open to all. Come for a college tour, a museum visit, a lecture or simply a walk through the gardens — here is everything you need to plan your time at Brightwell.",crumbs:[{to:"/",label:"Home"},{to:"/about",label:"About"},{label:"Visitors"}],sections:[{heading:"Visiting the campus",body:["The main campus is pedestrian-friendly and open daily, with free entry to the University’s four museums and the Gibson Library’s public reading rooms.","Guided walking tours run twice a day and cover the historic colleges, the chapel and the garden quarter. Tours leave from the University Information Office, where you can also collect maps and tickets for special exhibitions."],aside:{title:"Plan your visit",rows:[["Information office","Open daily 09:00 – 17:30"],["Guided tours","Daily, two departures"],["Museums","Free entry"],["Accommodation","College guest rooms available"]],links:[["/map","Map and travel"],["/events","Open days and events"]]}},{heading:"Getting around with children or accessibility needs",body:["Most courtyards and museum routes are step-free, and wheelchairs are available to borrow from the information office. Pushchair access to the main colleges is possible along marked routes.","Assistance dogs are welcome everywhere on campus. Sensory guides to the museums are available to download or collect at the door."],list:{title:"Things to see",items:["Daily life of a working university — follow the students through the main quad.","The gothic chapel and its renovation-quality 19th-century organ.","The garden quarter, including the botanical court at Aminu College."]}},{heading:"Group visits and schools",body:["School groups are welcome throughout the year. Free self-led visit packs and educator-led sessions in the museums can be booked in advance, with priority given to state schools.","Conference and event guests are hosted through the conference office, with dedicated arrival and hospitality arrangements."],aside:{title:"Useful contacts",rows:[["Information office",`${o.phone}`],["Email","visitors@brightwell.ng"],["Group bookings","schools@brightwell.ng"]],links:[["/contact","Contact us"]]}}]})}export{r as default};
